// ==================== TOAST NOTIFICATION ====================
    let toastTimer = null;
    function showToast(message) {
      const toastEl = document.getElementById("toast");
      const toastMsgEl = document.getElementById("toastMsg");
      toastMsgEl.textContent = message;
      toastEl.classList.remove("hidden");
      toastEl.classList.add("flex");
      if (toastTimer) clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toastEl.classList.add("hidden");
        toastEl.classList.remove("flex");
      }, 2800);
    }

    // ==================== FOTO MOTOR DARI GAMBAR YANG DIKIRIM ====================
    const MOTOR_IMAGES = {
      "vario-black-red": "data:image/png;base64,",
      "beat-black": "data:image/png;base64,",
      "beat-blue": "data:image/png;base64,",
      "beat-gold": "data:image/png;base64,",
      "beat-white": "data:image/png;base64,",
      "scoopy-cream": "data:image/png;base64,",
      "vario-black": "data:image/png;base64,",
      "vario-red": "data:image/png;base64,",
      "crf-red": "data:image/png;base64,",
      "beat-red-black": "data:image/png;base64,",
    };

    function getMotorSvg(variant, customImgUrl = "") {
      const imageUrl = customImgUrl || MOTOR_IMAGES[variant] || MOTOR_IMAGES["vario-black-red"];
      return `<img src="${imageUrl}" alt="Foto ${variant || "motor"}" class="w-full h-full object-contain" loading="lazy" />`;
    }

    // ==================== DATA 13 MOTOR SESUAI DESAIN ====================
    let motorData = [
      { id: 1,  name: "Honda Vario 125 Street 2024", brand: "Honda", type: "Vario 125 Street 2024", plate: "N 1234 XXX", price: "Rp 180.000", status: "Tersedia",  date: "2026-10-11", variant: "vario-black-red", customImg: "" },
      { id: 2,  name: "Honda Beat Deluxe 2023/2024", brand: "Honda", type: "Beat Deluxe 2023/2024", plate: "N 5678 YYY", price: "Rp 83.000",  status: "Disewa",    date: "2026-10-12", variant: "beat-black",      customImg: "" },
      { id: 3,  name: "Honda Beat Deluxe 2026",      brand: "Honda", type: "Beat Deluxe 2026",      plate: "N 9101 XXX", price: "Rp 86.000",  status: "Perbaikan", date: "2026-10-13", variant: "beat-blue",       customImg: "" },
      { id: 4,  name: "Honda Beat Street 2024",      brand: "Honda", type: "Beat Street 2024",      plate: "N 9101 XXX", price: "Rp 86.000",  status: "Tersedia",  date: "2026-10-14", variant: "beat-gold",       customImg: "" },
      { id: 5,  name: "Honda Beat Street 2025",      brand: "Honda", type: "Beat Street 2025",      plate: "N 9101 XXX", price: "Rp 86.000",  status: "Disewa",    date: "2026-10-15", variant: "beat-white",      customImg: "" },
      { id: 6,  name: "Honda Scoopy Prestige 2023",  brand: "Honda", type: "Scoopy Prestige 2023",  plate: "N 9101 XXX", price: "Rp 86.000",  status: "Disewa",    date: "2026-10-16", variant: "scoopy-cream",    customImg: "" },
      { id: 7,  name: "Honda Vario CBS 2023",        brand: "Honda", type: "Vario CBS 2023",        plate: "N 9101 XXX", price: "Rp 86.000",  status: "Tersedia",  date: "2026-10-17", variant: "vario-black",     customImg: "" },
      { id: 8,  name: "Honda Vario ABS 2022",        brand: "Honda", type: "Vario ABS 2022",        plate: "N 9101 XXX", price: "Rp 86.000",  status: "Tersedia",  date: "2026-10-18", variant: "vario-red",       customImg: "" },
      { id: 9,  name: "Honda Trial by CRF 2024",     brand: "Honda", type: "Trial by CRF 2024",     plate: "N 9101 XXX", price: "Rp 86.000",  status: "Tersedia",  date: "2026-10-19", variant: "crf-red",         customImg: "" },
      { id: 10, name: "Honda Beat Deluxe 2021/2022", brand: "Honda", type: "Beat Deluxe 2021/2022", plate: "N 9101 XXX", price: "Rp 86.000",  status: "Tersedia",  date: "2026-10-20", variant: "beat-red-black",  customImg: "" },
      { id: 11, name: "Honda Vario 125 Street 2024", brand: "Honda", type: "Vario 125 Street 2024", plate: "N 9101 XXX", price: "Rp 86.000",  status: "Perbaikan", date: "2026-10-22", variant: "vario-black-red", customImg: "" },
      { id: 12, name: "Honda Vario 125 Street 2024", brand: "Honda", type: "Vario 125 Street 2024", plate: "N 9101 XXX", price: "Rp 86.000",  status: "Perbaikan", date: "2026-10-25", variant: "vario-black-red", customImg: "" },
      { id: 13, name: "Honda Vario 125 Street 2024", brand: "Honda", type: "Vario 125 Street 2024", plate: "N 9101 XXX", price: "Rp 86.000",  status: "Disewa",    date: "2026-10-28", variant: "vario-black-red", customImg: "" },
    ];

    // ==================== STATE FILTER & PAGINASI ====================
    let currentPage = 1;
    const rowsPerPage = 6;
    let tableSearchQuery = "";
    let selectedStatusFilter = "Semua";
    let filterStartDate = "";
    let filterEndDate = "";

    function getFilteredMotors() {
      return motorData.filter(m => {
        const q = tableSearchQuery.toLowerCase();
        const matchSearch =
          m.name.toLowerCase().includes(q) ||
          m.brand.toLowerCase().includes(q) ||
          m.type.toLowerCase().includes(q) ||
          m.plate.toLowerCase().includes(q) ||
          m.status.toLowerCase().includes(q);

        const matchStatus = selectedStatusFilter === "Semua" || m.status === selectedStatusFilter;

        let matchDate = true;
        if (filterStartDate && m.date < filterStartDate) matchDate = false;
        if (filterEndDate && m.date > filterEndDate) matchDate = false;

        return matchSearch && matchStatus && matchDate;
      });
    }

    function updateDashboardStats() {
      const total = motorData.length;
      const avail = motorData.filter(m => m.status === "Tersedia").length;
      const rented = motorData.filter(m => m.status === "Disewa").length;
      const repair = motorData.filter(m => m.status === "Perbaikan").length;

      document.getElementById("dashTotalUnits").textContent = total;
      document.getElementById("dashAvailUnits").textContent = avail;
      document.getElementById("dashRentedUnits").textContent = rented;
      document.getElementById("dashRepairUnits").textContent = repair;
      document.getElementById("donutTotalText").textContent = total;
      document.getElementById("legendAvailCount").textContent = avail;
      document.getElementById("legendRentedCount").textContent = rented;
      document.getElementById("legendRepairCount").textContent = repair;

      const availPct = total ? Math.round((avail / total) * 100) : 0;
      const rentedPct = total ? Math.round((rented / total) * 100) : 0;
      document.getElementById("dashAvailPct").textContent = `${availPct}% dari total kapasitas`;
      document.getElementById("dashRentedPct").textContent = `Tingkat utilisasi ${rentedPct}%`;
    }

    function renderMotorTable() {
      const filtered = getFilteredMotors();
      const totalPages = Math.max(1, Math.ceil(filtered.length / rowsPerPage));
      if (currentPage > totalPages) currentPage = totalPages;

      const startIdx = (currentPage - 1) * rowsPerPage;
      const pageItems = filtered.slice(startIdx, startIdx + rowsPerPage);
      const tbody = document.getElementById("motorTableBody");

      if (pageItems.length === 0) {
        tbody.innerHTML = `
          <tr>
            <td colspan="9" class="py-10 text-center text-gray-400 text-[13px] font-medium">
              Tidak ada data motor yang sesuai dengan filter yang dipilih.
            </td>
          </tr>
        `;
      } else {
        tbody.innerHTML = pageItems.map((m, idx) => {
          const rowNum = startIdx + idx + 1;
          const badge =
            m.status === "Tersedia"
              ? "bg-[#DCFCE7] text-[#15803D] hover:bg-[#bbf7d0]"
              : m.status === "Disewa"
                ? "bg-[#FEF3C7] text-[#B45309] hover:bg-[#fde68a]"
                : "bg-[#FEE2E2] text-[#DC2626] hover:bg-[#fecaca]";

          return `
            <tr class="hover:bg-gray-50/80 transition-colors">
              <td class="py-3.5 px-4 text-center font-bold text-gray-800">${rowNum}</td>
              <td class="py-3 px-4 text-center">
                <div class="w-28 h-[76px] rounded-lg overflow-hidden mx-auto bg-white border border-gray-100 flex items-center justify-center p-1">
                  ${getMotorSvg(m.variant, m.customImg)}
                </div>
              </td>
              <td class="py-3.5 px-4 font-bold text-gray-900">${m.name}</td>
              <td class="py-3.5 px-4 text-gray-700">${m.brand}</td>
              <td class="py-3.5 px-4 text-gray-700">${m.type}</td>
              <td class="py-3.5 px-5 min-w-[160px] whitespace-nowrap font-bold text-gray-800">${m.plate}</td>
              <td class="py-3.5 px-4 font-bold text-gray-900">${m.price}</td>
              <td class="py-3.5 px-4 text-center">
                <button
                  type="button"
                  onclick="cycleMotorStatus(${m.id})"
                  title="Klik untuk ubah status (Tersedia / Disewa / Perbaikan)"
                  class="inline-flex items-center justify-center min-w-[84px] px-3 py-1.5 rounded-full text-[11px] font-bold transition-all cursor-pointer hover:shadow-sm active:scale-95 ${badge}"
                >
                  <span>${m.status}</span>
                </button>
              </td>
              <td class="py-3.5 px-4 text-center">
                <div class="flex items-center justify-center gap-1.5">
                  <button type="button" onclick="openMotorModal(${m.id}, 'detail')" title="Lihat Detail" class="p-1.5 rounded-lg bg-[#E6F2F4] text-[#0C4651] hover:bg-[#0C4651] hover:text-white transition-colors"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg></button>
                  <button type="button" onclick="openMotorModal(${m.id}, 'edit')" title="Ubah Status & Harga" class="p-1.5 rounded-lg bg-gray-100 text-gray-700 hover:bg-gray-700 hover:text-white transition-colors"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg></button>
                  <button type="button" onclick="deleteMotor(${m.id})" title="Hapus Motor" class="p-1.5 rounded-lg bg-red-50 text-[#EF4444] hover:bg-red-500 hover:text-white transition-colors"><svg class="w-4 h-4" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg></button>
                </div>
              </td>
            </tr>
          `;
        }).join("");
      }

      const endDisplay = filtered.length === 0 ? 0 : Math.min(startIdx + rowsPerPage, filtered.length);
      const startDisplay = filtered.length === 0 ? 0 : startIdx + 1;
      document.getElementById("motorPaginationInfo").textContent = `Menampilkan ${startDisplay} - ${endDisplay} dari ${filtered.length} data`;

      let pHtml = `<button type="button" onclick="goToPage(${currentPage - 1})" ${currentPage === 1 ? "disabled" : ""} class="w-7 h-7 rounded-full border border-[#0C4651]/40 text-[#0C4651] flex items-center justify-center text-xs hover:bg-[#0C4651] hover:text-white disabled:opacity-35">&#8249;</button>`;
      for (let p = 1; p <= totalPages; p++) {
        pHtml += `<button type="button" onclick="goToPage(${p})" class="w-7 h-7 rounded-full border text-[11.5px] font-bold flex items-center justify-center ${p === currentPage ? "bg-[#0C4651] text-white border-[#0C4651]" : "bg-white text-[#0C4651] border-[#0C4651]/40"}">${p}</button>`;
      }
      pHtml += `<button type="button" onclick="goToPage(${currentPage + 1})" ${currentPage === totalPages ? "disabled" : ""} class="w-7 h-7 rounded-full border border-[#0C4651]/40 text-[#0C4651] flex items-center justify-center text-xs hover:bg-[#0C4651] hover:text-white disabled:opacity-35">&#8250;</button>`;
      document.getElementById("motorPaginationControls").innerHTML = pHtml;
      updateDashboardStats();
    }

    window.goToPage = (p) => { currentPage = p; renderMotorTable(); };

    // ==================== UBAH STATUS & AKSI TABEL ====================
    window.cycleMotorStatus = function (id) {
      const order = ["Tersedia", "Disewa", "Perbaikan"];
      const item = motorData.find(m => m.id === id);
      if (!item) return;
      const nextIdx = (order.indexOf(item.status) + 1) % order.length;
      item.status = order[nextIdx];
      renderMotorTable();
      showToast(`Status ${item.name} diubah menjadi "${item.status}"`);
    };

    window.deleteMotor = function (id) {
      const item = motorData.find(m => m.id === id);
      if (!item) return;
      motorData = motorData.filter(m => m.id !== id);
      renderMotorTable();
      showToast(`Unit ${item.name} telah dihapus`);
    };

    const motorModal = document.getElementById("motorModal");
    window.openMotorModal = function (id, mode) {
      const m = motorData.find(x => x.id === id);
      if (!m) return;
      const rawNumericPrice = parseInt(m.price.replace(/[^0-9]/g, ""), 10) || 85000;
      document.getElementById("modalTitle").textContent = mode === "edit" ? "Ubah Status & Harga Motor" : "Detail Unit Motor";
      document.getElementById("modalBody").innerHTML = `
        <div class="flex items-center gap-4 p-3 rounded-xl bg-gray-50 border border-gray-100">
          <div class="w-24 h-16 bg-white rounded-lg border border-gray-200 flex items-center justify-center p-1 shrink-0">
            ${getMotorSvg(m.variant, m.customImg)}
          </div>
          <div>
            <div class="text-[14px] font-extrabold text-gray-900">${m.name}</div>
            <div class="text-[12px] text-gray-500">${m.plate} • ${m.price}/hari</div>
            <div class="text-[11px] text-gray-400 mt-0.5">Terdaftar: ${m.date}</div>
          </div>
        </div>
        <div>
          <label class="block text-[12px] font-bold text-gray-700 mb-1.5">Status Unit Motor</label>
          <select id="modalStatusSelect" class="w-full bg-white border border-gray-200 rounded-xl px-3.5 py-2.5 text-[13px] font-bold text-gray-800 outline-none focus:border-[#0C4651]">
            <option value="Tersedia" ${m.status === "Tersedia" ? "selected" : ""}>Tersedia (Siap Sewa)</option>
            <option value="Disewa" ${m.status === "Disewa" ? "selected" : ""}>Disewa (Sedang Digunakan)</option>
            <option value="Perbaikan" ${m.status === "Perbaikan" ? "selected" : ""}>Perbaikan (Servis Bengkel)</option>
          </select>
        </div>
        ${mode === "edit" ? `
        <div>
          <label class="block text-[12px] font-bold text-gray-700 mb-1.5">Harga Sewa per Hari (Rp)</label>
          <input type="number" id="modalPriceInput" value="${rawNumericPrice}" class="w-full bg-white border border-gray-200 rounded-xl px-3.5 py-2.5 text-[13px] font-bold text-gray-800 outline-none focus:border-[#0C4651]" />
        </div>` : ""}
        <div class="flex justify-end gap-2 pt-2">
          <button type="button" onclick="closeMotorModal()" class="px-4 py-2 rounded-xl border border-gray-200 text-xs font-bold text-gray-600 hover:bg-gray-50">Tutup</button>
          <button type="button" onclick="saveModalStatus(${m.id})" class="px-4 py-2 rounded-xl bg-[#0C4651] text-white text-xs font-bold hover:bg-[#093841]">Simpan Perubahan</button>
        </div>
      `;
      motorModal.classList.remove("hidden");
      motorModal.classList.add("flex");
    };

    window.closeMotorModal = function () {
      motorModal.classList.add("hidden");
      motorModal.classList.remove("flex");
    };

    window.saveModalStatus = function (id) {
      const m = motorData.find(x => x.id === id);
      const val = document.getElementById("modalStatusSelect").value;
      const priceInput = document.getElementById("modalPriceInput");
      if (m) {
        m.status = val;
        if (priceInput && priceInput.value) {
          const num = parseInt(priceInput.value, 10) || 85000;
          m.price = "Rp " + num.toLocaleString("id-ID");
        }
        renderMotorTable();
        showToast(`Data ${m.name} berhasil diperbarui`);
      }
      closeMotorModal();
    };
    document.getElementById("closeModalBtn").addEventListener("click", closeMotorModal);

    // ==================== DROPDOWN FILTER KALENDER ====================
    const calendarTriggerBtn = document.getElementById("calendarTriggerBtn");
    const calendarPopover = document.getElementById("calendarPopover");
    const calendarLabel = document.getElementById("calendarLabel");
    const startDateInput = document.getElementById("startDateInput");
    const endDateInput = document.getElementById("endDateInput");

    function formatIndoDate(isoStr) {
      if (!isoStr) return "";
      const months = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
      const [y, m, d] = isoStr.split("-");
      return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
    }

    calendarTriggerBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      statusPopover.classList.add("hidden");
      profilePopover.classList.add("hidden");
      calendarPopover.classList.toggle("hidden");
    });

    calendarPopover.addEventListener("click", (e) => e.stopPropagation());

    document.getElementById("applyDateFilterBtn").addEventListener("click", () => {
      filterStartDate = startDateInput.value;
      filterEndDate = endDateInput.value;
      if (filterStartDate && filterEndDate) {
        calendarLabel.textContent = `${formatIndoDate(filterStartDate)} – ${formatIndoDate(filterEndDate)}`;
      } else if (filterStartDate) {
        calendarLabel.textContent = `Mulai ${formatIndoDate(filterStartDate)}`;
      } else if (filterEndDate) {
        calendarLabel.textContent = `Sampai ${formatIndoDate(filterEndDate)}`;
      } else {
        calendarLabel.textContent = "Semua Tanggal";
      }
      currentPage = 1;
      renderMotorTable();
      calendarPopover.classList.add("hidden");
      showToast("Filter kalender diterapkan");
    });

    document.getElementById("presetOctBtn").addEventListener("click", () => {
      startDateInput.value = "2026-10-11";
      endDateInput.value = "2026-10-20";
      document.getElementById("applyDateFilterBtn").click();
    });

    document.getElementById("presetAllDateBtn").addEventListener("click", () => {
      startDateInput.value = "";
      endDateInput.value = "";
      filterStartDate = "";
      filterEndDate = "";
      calendarLabel.textContent = "Semua Tanggal";
      currentPage = 1;
      renderMotorTable();
      calendarPopover.classList.add("hidden");
      showToast("Menampilkan semua tanggal");
    });

    document.getElementById("resetDateFilterBtn").addEventListener("click", () => {
      document.getElementById("presetAllDateBtn").click();
    });

    // ==================== DROPDOWN FILTER SEMUA STATUS ====================
    const statusTriggerBtn = document.getElementById("statusTriggerBtn");
    const statusPopover = document.getElementById("statusPopover");
    const statusFilterLabel = document.getElementById("statusFilterLabel");

    statusTriggerBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      calendarPopover.classList.add("hidden");
      profilePopover.classList.add("hidden");
      statusPopover.classList.toggle("hidden");
    });

    document.querySelectorAll(".status-option").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        selectedStatusFilter = btn.dataset.statusVal;
        statusFilterLabel.textContent = selectedStatusFilter === "Semua" ? "Semua Status" : selectedStatusFilter;
        document.querySelectorAll(".status-option").forEach(el => {
          el.classList.remove("text-[#0C4651]", "bg-[#E6F2F4]/60", "font-bold");
          el.classList.add("text-gray-700", "font-semibold");
        });
        btn.classList.add("text-[#0C4651]", "bg-[#E6F2F4]/60", "font-bold");
        btn.classList.remove("text-gray-700", "font-semibold");
        statusPopover.classList.add("hidden");
        currentPage = 1;
        renderMotorTable();
      });
    });

    // ==================== SEARCH INPUTS ====================
    document.getElementById("tableSearchInput").addEventListener("input", (e) => {
      tableSearchQuery = e.target.value;
      currentPage = 1;
      renderMotorTable();
    });

    document.getElementById("globalSearchInput").addEventListener("input", (e) => {
      tableSearchQuery = e.target.value;
      document.getElementById("tableSearchInput").value = tableSearchQuery;
      currentPage = 1;
      renderMotorTable();
    });

    // ==================== FORM TAMBAH MOTOR BARU ====================
    let uploadedMotorImage = "";
    const motorPhotoInput = document.getElementById("motorPhotoInput");
    const photoPreviewBox = document.getElementById("photoPreviewBox");
    const presetBikeStyle = document.getElementById("presetBikeStyle");

    document.getElementById("choosePhotoBtn").addEventListener("click", () => motorPhotoInput.click());

    motorPhotoInput.addEventListener("change", (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (ev) => {
        uploadedMotorImage = ev.target.result;
        photoPreviewBox.innerHTML = `<img src="${uploadedMotorImage}" alt="Preview" class="w-full h-full object-contain" />`;
      };
      reader.readAsDataURL(file);
    });

    presetBikeStyle.addEventListener("change", () => {
      if (!uploadedMotorImage) {
        photoPreviewBox.innerHTML = getMotorSvg(presetBikeStyle.value);
      }
    });

    document.getElementById("addMotorForm").addEventListener("submit", (e) => {
      e.preventDefault();
      const name = document.getElementById("inputMotorName").value.trim();
      const brand = document.getElementById("inputMotorBrand").value.trim();
      const type = document.getElementById("inputMotorType").value.trim();
      const plate = document.getElementById("inputMotorPlate").value.trim();
      const rawPrice = parseInt(document.getElementById("inputMotorPrice").value, 10) || 85000;
      const status = document.querySelector('input[name="statusMotor"]:checked').value;
      const variant = presetBikeStyle.value;

      const newId = motorData.length ? Math.max(...motorData.map(m => m.id)) + 1 : 1;
      const todayIso = new Date().toISOString().split("T")[0];

      motorData.unshift({
        id: newId,
        name,
        brand,
        type,
        plate,
        price: "Rp " + rawPrice.toLocaleString("id-ID"),
        status,
        date: todayIso,
        variant,
        customImg: uploadedMotorImage
      });

      e.target.reset();
      uploadedMotorImage = "";
      photoPreviewBox.innerHTML = `<svg class="w-8 h-8 text-gray-300 mb-1" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24"><circle cx="12" cy="13" r="4"/><path stroke-linecap="round" d="M5 7h2l1.5-2h7L17 7h2a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9a2 2 0 012-2z"/></svg><span class="text-[11px] font-medium text-gray-500">Belum ada foto</span>`;
      currentPage = 1;
      renderMotorTable();
      switchView("motor");
      showToast(`Motor "${name}" berhasil ditambahkan!`);
    });

    // ==================== RENDER DASHBOARD CHART & TRANSAKSI ====================
    function renderDashboardWidgets() {
      const revenueData = [
        { label: "1 Sep", value: 4950000, pct: 73, highlight: false },
        { label: "2 Sep", value: 3900000, pct: 57, highlight: false },
        { label: "3 Sep", value: 4600000, pct: 68, highlight: false },
        { label: "4 Sep", value: 5500000, pct: 81, highlight: false },
        { label: "5 Sep", value: 4100000, pct: 60, highlight: false },
        { label: "6 Sep", value: 2700000, pct: 40, highlight: false },
        { label: "7 Sep", value: 4350000, pct: 64, highlight: false },
        { label: "8 Sep", value: 5200000, pct: 76, highlight: false },
        { label: "9 Sep", value: 6250000, pct: 92, highlight: true  },
      ];
      document.getElementById("revenueBarsContainer").innerHTML = revenueData.map(item => {
        const barColor = item.highlight ? "bg-[#083B44] ring-2 ring-[#10B981]/60" : "bg-[#436368] hover:bg-[#0C4651]";
        const dot = item.highlight ? `<span class="absolute -top-1.5 left-1/2 -translate-x-1/2 w-2.5 h-2.5 rounded-full bg-[#10B981] ring-2 ring-white"></span>` : "";
        return `
          <div class="flex flex-col items-center h-full justify-end group relative">
            <div class="opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none absolute -top-8 bg-[#0C4651] text-white text-[10px] font-bold px-2 py-1 rounded-md whitespace-nowrap shadow-md z-10">
              Rp ${item.value.toLocaleString("id-ID")}
            </div>
            <div class="w-full max-w-[26px] flex-1 flex items-end mb-6">
              <div style="height: ${item.pct}%" class="w-full rounded-t-lg ${barColor} transition-all duration-300 relative cursor-pointer">${dot}</div>
            </div>
            <span class="absolute bottom-0 text-[10.5px] font-semibold ${item.highlight ? "text-[#0C4651] font-bold" : "text-gray-400"} whitespace-nowrap">${item.label}</span>
          </div>
        `;
      }).join("");

      const txList = [
        { no: 1, user: "Hash Aurelia",    motor: "Honda Vario 125", date: "18 Oktober 2026", status: "Aktif",   total: "Rp 83.000" },
        { no: 2, user: "Reyna Putri",     motor: "Honda Vario 125", date: "19 Oktober 2026", status: "Aktif",   total: "Rp 130.000" },
        { no: 3, user: "Jett Oktavia",    motor: "Honda Vario 125", date: "20 Oktober 2026", status: "Aktif",   total: "Rp 150.000" },
        { no: 4, user: "Phoenix Saputra", motor: "Honda Vario 125", date: "21 Oktober 2026", status: "Selesai", total: "Rp 180.000" },
        { no: 5, user: "Sova Mahendra",   motor: "Honda Vario 125", date: "22 Oktober 2026", status: "Selesai", total: "Rp 200.000" },
      ];
      document.getElementById("dashTransactionBody").innerHTML = txList.map(t => `
        <tr class="hover:bg-gray-50/80 transition-colors">
          <td class="py-3.5 px-4 text-center font-bold text-gray-800">${t.no}</td>
          <td class="py-3.5 px-4 font-bold text-gray-900">${t.user}</td>
          <td class="py-3.5 px-4 font-bold text-gray-800">${t.motor}</td>
          <td class="py-3.5 px-4 font-bold text-gray-800">${t.date}</td>
          <td class="py-3.5 px-4 text-center"><span class="inline-block min-w-[68px] px-3 py-1 rounded-full text-[11px] font-bold ${t.status === "Aktif" ? "bg-[#DCFCE7] text-[#15803D]" : "bg-[#DBEAFE] text-[#2563EB]"}">${t.status}</span></td>
          <td class="py-3.5 px-4 text-right pr-6 font-bold text-gray-900">${t.total}</td>
        </tr>
      `).join("");
    }

    // ==================== NAVIGASI VIEW & SIDEBAR ====================
    window.switchView = function (target) {
      document.querySelectorAll(".nav-item").forEach(btn => {
        const active = btn.dataset.nav === target || (target === "add-motor" && btn.dataset.nav === "motor");
        btn.classList.toggle("bg-white", active);
        btn.classList.toggle("text-[#0C4651]", active);
        btn.classList.toggle("font-semibold", active);
        btn.classList.toggle("shadow-sm", active);
        btn.classList.toggle("text-white/85", !active);
        btn.classList.toggle("font-medium", !active);
      });

      document.getElementById("view-motor").classList.add("hidden");
      document.getElementById("view-add-motor").classList.add("hidden");
      document.getElementById("view-dashboard").classList.add("hidden");
      document.getElementById("view-secondary").classList.add("hidden");

      if (target === "motor") {
        document.getElementById("view-motor").classList.remove("hidden");
      } else if (target === "add-motor") {
        document.getElementById("view-add-motor").classList.remove("hidden");
      } else if (target === "dashboard") {
        document.getElementById("view-dashboard").classList.remove("hidden");
      } else {
        const titles = {
          transaksi: "Kelola Transaksi",
          penyewaan: "Info Penyewaan",
          pembayaran: "Pembayaran",
          pengaturan: "Pengaturan Sistem"
        };
        document.getElementById("secondaryTitle").textContent = titles[target] || target.toUpperCase();
        document.getElementById("secondarySubtitle").textContent = `Modul ${titles[target] || target} RYOKOU Oto Rent.`;
        document.getElementById("secondaryContent").innerHTML = `
          <div class="bg-white rounded-2xl p-6 card-shadow border border-gray-100 col-span-full">
            <h3 class="text-lg font-bold text-gray-900 mb-2">${titles[target] || target}</h3>
            <p class="text-gray-500 text-sm">Modul operasional RYOKOU Oto Rent aktif dan siap digunakan.</p>
          </div>
        `;
        document.getElementById("view-secondary").classList.remove("hidden");
      }

      if (window.innerWidth < 1024) {
        sidebar.classList.add("-translate-x-full");
        mobileBackdrop.classList.add("hidden");
      }
      window.scrollTo({ top: 0, behavior: "smooth" });
    };

    document.querySelectorAll("[data-nav]").forEach(btn => {
      btn.addEventListener("click", () => switchView(btn.dataset.nav));
    });
    document.getElementById("openAddMotorBtn").addEventListener("click", () => switchView("add-motor"));
    document.getElementById("backToMotorBtn").addEventListener("click", () => switchView("motor"));

    // Sidebar Toggle
    const sidebar = document.getElementById("sidebar");
    const mobileBackdrop = document.getElementById("mobileBackdrop");
    let isCollapsed = false;

    document.getElementById("toggleSidebarBtn").addEventListener("click", () => {
      if (window.innerWidth >= 1024) {
        isCollapsed = !isCollapsed;
        sidebar.classList.toggle("sidebar-collapsed", isCollapsed);
        sidebar.classList.toggle("sidebar-expanded", !isCollapsed);
        document.getElementById("toggleIconOpen").classList.toggle("hidden", isCollapsed);
        document.getElementById("toggleIconClosed").classList.toggle("hidden", !isCollapsed);
      } else {
        sidebar.classList.toggle("-translate-x-full");
        mobileBackdrop.classList.toggle("hidden");
      }
    });

    document.getElementById("closeMobileSidebarBtn").addEventListener("click", () => {
      sidebar.classList.add("-translate-x-full");
      mobileBackdrop.classList.add("hidden");
    });
    mobileBackdrop.addEventListener("click", () => {
      sidebar.classList.add("-translate-x-full");
      mobileBackdrop.classList.add("hidden");
    });

    // Profile Dropdown
    const profileTrigger = document.getElementById("profileTrigger");
    const profilePopover = document.getElementById("profilePopover");
    profileTrigger.addEventListener("click", (e) => {
      e.stopPropagation();
      calendarPopover.classList.add("hidden");
      statusPopover.classList.add("hidden");
      profilePopover.classList.toggle("hidden");
    });

    document.addEventListener("click", () => {
      profilePopover.classList.add("hidden");
      calendarPopover.classList.add("hidden");
      statusPopover.classList.add("hidden");
    });

    const logoutFn = () => showToast("Berhasil keluar dari sistem (Admin_001)");
    document.getElementById("sidebarLogoutBtn").addEventListener("click", logoutFn);
    document.getElementById("popoverLogoutBtn").addEventListener("click", logoutFn);

    // Inisialisasi Awal
    renderDashboardWidgets();
    renderMotorTable();
